{
  "name": "move",
  "type": "function",
  "description": "Moves one or more tabs to a new position within its current window, or to a different window. Tabs can only be moved to and from windows of type <var>normal</var>. The primary mail tab cannot be moved, attempting to actively reposition it will throw an <em>ExtensionError</em>. Other tabs also cannot be placed before the primary mail tab, they will automatically be positioned after it, ensuring that the primary mail tab always remains first.",
  "async": "callback",
  "parameters": [
    {
      "name": "tabIds",
      "description": "The tab or list of tabs to move.",
      "choices": [
        {
          "type": "integer",
          "minimum": 0
        },
        {
          "type": "array",
          "items": {
            "type": "integer",
            "minimum": 0
          }
        }
      ]
    },
    {
      "type": "object",
      "name": "moveProperties",
      "properties": {
        "windowId": {
          "type": "integer",
          "minimum": -2,
          "optional": true,
          "description": "Defaults to the window the tab is currently in."
        },
        "index": {
          "type": "integer",
          "minimum": -1,
          "description": "The position to move the tab to. <var>-1</var> will place the tab at the end of the window."
